CREATE TABLE asset_gen_tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  generate_uuid TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'submitted',
  prompt TEXT,
  negative_prompt TEXT,
  width INTEGER,
  height INTEGER,
  img_count INTEGER,
  sampler INTEGER,
  steps INTEGER,
  cfg_scale REAL,
  seed INTEGER,
  template_uuid TEXT,
  checkpoint_id TEXT,
  liblib_status INTEGER,
  image_url TEXT,
  local_path TEXT,
  submitted_at TEXT,
  completed_at TEXT,
  error_msg TEXT
);

