CREATE TABLE battle_config (config_key text primary key, config_value real not null);
CREATE TABLE bgm_defs (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    style TEXT NOT NULL CHECK(style IN ('soothing','stirring')),
    pool TEXT NOT NULL CHECK(pool IN ('title','alliance_day','alliance_night','horde_day','horde_night','result')),
    uid TEXT NOT NULL
);
CREATE TABLE building_defs (
    type_id           TEXT PRIMARY KEY,
    display_name      TEXT    NOT NULL,
    max_health        INTEGER NOT NULL,
    spawn_interval    REAL,
    main_cell_x       INTEGER DEFAULT 0,
    main_cell_y       INTEGER DEFAULT 0,
    spawn_cell_x      INTEGER DEFAULT 0,
    spawn_cell_y      INTEGER DEFAULT 0,
    unit_type_id      TEXT,
    has_night_combat  INTEGER DEFAULT 0,
    combine_tier       INTEGER DEFAULT 0,
    is_core           INTEGER DEFAULT 0,
    footprint_json    TEXT    NOT NULL,
    collision_width   INTEGER NOT NULL DEFAULT 80,
    collision_height  INTEGER NOT NULL DEFAULT 80
, faction_id TEXT NOT NULL DEFAULT 'human', production_rate REAL NOT NULL DEFAULT 0.0, texture_path TEXT NOT NULL DEFAULT 'res://assets/art/placeholders/test_image.png', sprite_modulate_r REAL NOT NULL DEFAULT 1.0, sprite_modulate_g REAL NOT NULL DEFAULT 1.0, sprite_modulate_b REAL NOT NULL DEFAULT 1.0, sprite_modulate_a REAL NOT NULL DEFAULT 1.0, material_path TEXT NOT NULL DEFAULT '', value INTEGER, race_id TEXT NOT NULL DEFAULT '', texture_uid TEXT, shop_available INTEGER NOT NULL DEFAULT 0, gold_cost INTEGER NOT NULL DEFAULT 0, shop_weight INTEGER NOT NULL DEFAULT 1);
CREATE TABLE "combine_recipes" (
                main_type_id TEXT NOT NULL,
                material_type_id TEXT NOT NULL,
                material_count INTEGER NOT NULL,
                result_type_id TEXT NOT NULL,
                PRIMARY KEY (main_type_id, material_type_id, result_type_id)
            );
CREATE TABLE "damage_matrix" (damage_type INTEGER NOT NULL, armor_type INTEGER NOT NULL, multiplier INTEGER NOT NULL, PRIMARY KEY (damage_type, armor_type));
CREATE TABLE display_config (config_key text primary key, config_value real not null);
CREATE TABLE economy_config (config_key text primary key, config_value real not null);
CREATE TABLE "faction_defs" (
    id TEXT PRIMARY KEY,
    display_name TEXT NOT NULL,
    sort_order INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE faction_inventory (
        faction_id TEXT NOT NULL,
        type_id TEXT NOT NULL,
        PRIMARY KEY (faction_id, type_id)
    );
CREATE TABLE item_catalog (id TEXT PRIMARY KEY, name TEXT NOT NULL, cost INTEGER NOT NULL, weight INTEGER NOT NULL DEFAULT 1, faction_id TEXT NOT NULL DEFAULT '', item_type TEXT NOT NULL DEFAULT '', attributes TEXT NOT NULL DEFAULT '');
CREATE TABLE shop_catalog (
    id            TEXT PRIMARY KEY,
    name          TEXT    NOT NULL,
    cost          INTEGER NOT NULL,
    building_type TEXT    NOT NULL,
    weight        INTEGER NOT NULL DEFAULT 1
, unlock_ritual_id TEXT, unlock_night INTEGER NOT NULL DEFAULT 1);
CREATE TABLE "skill_defs" (
    id TEXT PRIMARY KEY,
    display_name TEXT NOT NULL,
    skill_type TEXT NOT NULL CHECK(skill_type IN ('stat_modifier','aura','on_hit','on_heal','special')),
    config_json TEXT NOT NULL
, description TEXT, icon_uid TEXT);
CREATE TABLE sound_config (config_key text primary key, config_value real not null);
CREATE TABLE tech_tree_nodes (
    type_id TEXT PRIMARY KEY,
    faction_id TEXT NOT NULL REFERENCES "faction_defs"(id),
    tier INTEGER NOT NULL CHECK(tier BETWEEN 1 AND 5),
    col INTEGER NOT NULL DEFAULT 0,
    shop_available INTEGER NOT NULL DEFAULT 0,
    gold_cost INTEGER,
    shop_weight INTEGER,
    unlock_night INTEGER DEFAULT 0,
    display_name TEXT NOT NULL,
    unit_type_id TEXT,
    max_health INTEGER NOT NULL DEFAULT 200,
    spawn_interval REAL NOT NULL DEFAULT 10.0
, value INTEGER, race_id TEXT NOT NULL DEFAULT '', is_core INTEGER NOT NULL DEFAULT 0);
CREATE TABLE unit_skills (
    unit_type_id TEXT NOT NULL,
    skill_id TEXT NOT NULL,
    PRIMARY KEY (unit_type_id, skill_id)
);
CREATE TABLE unit_stats (
    type_id          TEXT PRIMARY KEY,
    size             INTEGER NOT NULL,
    attack_type      INTEGER NOT NULL,
    damage_type      INTEGER NOT NULL,
    armor_type       INTEGER NOT NULL,
    health           INTEGER NOT NULL,
    damage           INTEGER NOT NULL,
    speed            REAL    NOT NULL,
    attack_range     REAL    NOT NULL,
    attack_cooldown  REAL    NOT NULL,
    has_night_combat INTEGER NOT NULL DEFAULT 0,
    unit_color       INTEGER NOT NULL,
    vision_range     REAL    NOT NULL DEFAULT 170.0
, unit_cost INTEGER NOT NULL DEFAULT 2000, race TEXT NOT NULL DEFAULT '', armor_value INTEGER NOT NULL DEFAULT 0, can_detect_stealth INTEGER NOT NULL DEFAULT 0, heal_amount REAL NOT NULL DEFAULT 0, heal_range REAL NOT NULL DEFAULT 0, heal_interval REAL NOT NULL DEFAULT 0, portrait_uid TEXT);
CREATE TABLE upgrade_recipes (
    source_type_id TEXT NOT NULL,
    result_type_id TEXT NOT NULL,
    PRIMARY KEY (source_type_id, result_type_id)
);
DELETE FROM "sqlite_sequence";
COMMIT;
